"""
sl_post.py  —  Luraph Skid v4 post-processor
Ported from lphx.py (SL | Source Leak) by Claude.

Provides:
  finalize(text) -> str    full pipeline: sanitize + prettify + smart_rename + watermark
  process_file(path)       in-place finalize on a UTF-8 file
"""

import os
import re

# ---------------------------------------------------------------------------
# Constants shared with the original prettifier
# ---------------------------------------------------------------------------
WATERMARK = (
    "-- generated by Luraph Skid v4 (SL | Source Leak)\n"
    "-- https://discord.gg/x7YbZeezpm\n"
)

KEYWORDS = {
    "and", "break", "do", "else", "elseif", "end", "false", "for", "function",
    "if", "in", "local", "nil", "not", "or", "repeat", "return", "then", "true",
    "until", "while", "continue", "type", "export",
}

GLOBALS = {
    "type", "pcall", "xpcall", "error", "tostring", "tonumber", "ipairs", "pairs",
    "next", "select", "rawget", "rawset", "rawequal", "rawlen", "setmetatable",
    "getmetatable", "unpack", "assert", "print", "warn", "require", "loadstring",
    "getgenv", "getfenv", "setfenv", "getrenv", "getreg", "getgc", "identifyexecutor",
    "_G", "shared", "game", "workspace", "script", "string", "table", "math", "os",
    "bit32", "task", "buffer", "coroutine", "utf8", "debug", "Instance", "Vector3",
    "Vector2", "CFrame", "Color3", "UDim2", "UDim", "Enum", "tick", "time", "wait",
    "spawn", "delay", "typeof", "newproxy", "gcinfo", "collectgarbage", "syn",
    "request", "http_request", "hookfunction", "hookmetamethod", "newcclosure",
    "checkcaller", "getnamecallmethod", "setclipboard", "writefile", "readfile",
    "isfile", "makefolder", "isfolder", "delfile", "listfiles", "crypt", "Drawing",
    "firesignal", "fireclickdetector", "firetouchinterest", "getconnections",
    "cloneref", "gethui", "getcustomasset", "queue_on_teleport", "decompile",
}

LIBS = {
    "string", "table", "math", "os", "bit32", "task", "buffer", "coroutine", "utf8", "debug",
}

WORD_HINTS = [
    (r"^\s*\w+\.create\(", "arr"), (r"^\s*table\.create\(", "arr"),
    (r"^\s*\w+\.clock\(\)", "startTime"), (r"^\s*\w+\.time\(\)", "timestamp"),
    (r"^\s*tick\(\)", "startTime"), (r"^\s*\w+\.gsub\(", "cleaned"),
    (r"^\s*\w+\.sub\(", "substr"), (r"^\s*\w+\.format\(", "formatted"),
    (r"^\s*\w+\.concat\(", "joined"), (r"^\s*\w+\.lower\(", "lowered"),
    (r"^\s*\w+\.upper\(", "uppered"), (r"^\s*\w+\.match\(", "matched"),
    (r"^\s*\w+\.find\(", "foundAt"), (r"^\s*\w+\.byte\(", "byte"),
    (r"^\s*\w+\.char\(", "char"), (r"^\s*\w+\.rep\(", "repeated"),
    (r"^\s*\w+\.floor\(", "floored"), (r"^\s*\w+\.ceil\(", "ceiled"),
    (r"^\s*\w+\.max\(", "maxValue"), (r"^\s*\w+\.min\(", "minValue"),
    (r"^\s*\w+\.bxor\(", "xored"), (r"^\s*\w+\.pack\(", "packed"),
    (r"^\s*\w+\.unpack\(", "unpacked"), (r"^\s*tostring\(", "str"),
    (r"^\s*tonumber\(", "num"), (r"^\s*#", "len"), (r"^\s*nil\s*$", "value"),
    (r"^\s*\{", "tbl"), (r'^\s*"', "str"), (r"^\s*-?\d", "num"),
    (r"^\s*(true|false)\s*$", "flag"), (r"^\s*function\b", "func"),
    (r"^\s*require\(", "module"), (r'^\s*Instance\.new\(\"(\w+)\"', None),
    (r"^\s*\w+\s*\.\.", "str"), (r"^\s*sha\d+\(", "hash"),
    (r"^\s*\w*[Dd]ecode\w*\(", "decoded"), (r"^\s*\w*[Ee]ncode\w*\(", "encoded"),
    (r"^\s*\w+\[1\]\s*$", "first"), (r"^\s*\w+\[2\]\s*$", "second"),
    (r"^\s*\w+\[3\]\s*$", "third"), (r"^\s*\w+\[[^\]]+\]\s*$", "entry"),
    (r"^\s*\w+\(\)\s*$", "result"),
]

TARGET_RE = re.compile(r"(v\d+|tbl\d+|fn\d*|arg\d*|value\d*)$")

TOKEN_RE = re.compile(r"""
    (?P<ws>\s+)
  | (?P<comment>--\[(?P<ceq>=*)\[.*?\](?P=ceq)\]|--[^\n]*)
  | (?P<lstr>\[(?P<leq>=*)\[.*?\](?P=leq)\])
  | (?P<str>"(?:\\.|[^"\\\n])*"|'(?:\\.|[^'\\\n])*'|`(?:\\.|[^`\\])*`)
  | (?P<num>0[xX][0-9a-fA-F_]+|0[bB][01_]+|\d[\d_]*(?:\.[\d_]*)?(?:[eE][+-]?\d+)?|\.\d+(?:[eE][+-]?\d+)?)
  | (?P<n>[A-Za-z_][A-Za-z0-9_]*)
  | (?P<op>\.\.\.|\.\.[.=]?|==|~=|<=|>=|//=?|::|[-+*/%^]=|->|.)
""", re.S | re.X)

# ---------------------------------------------------------------------------
# Tokenizer
# ---------------------------------------------------------------------------

def tokenize(src):
    toks = []
    pos = 0
    while pos < len(src):
        m = TOKEN_RE.match(src, pos)
        if not m:
            return None
        kind = m.lastgroup
        if kind in ("ceq", "leq"):
            kind = "comment" if m.group("comment") else "lstr"
        toks.append([kind, m.group(0)])
        pos = m.end()
    return toks


def analyze(toks):
    sig = [i for i, t in enumerate(toks) if t[0] not in ("ws", "comment")]
    binds = {}

    def add(n):
        binds[n] = binds.get(n, 0) + 1

    for k, i in enumerate(sig):
        kind, val = toks[i]
        prev = toks[sig[k - 1]][1] if k else ""
        if kind != "n" or val in KEYWORDS and val != "type":
            continue
        if prev in (".", ":"):
            continue
        j = k - 1
        while j >= 1 and toks[sig[j]][1] == "," and toks[sig[j - 1]][0] == "n":
            j -= 2
        head = toks[sig[j]][1] if j >= 0 else ""
        if head in ("local", "for", "function"):
            add(val)
            continue
        jj = k - 1
        while jj >= 0 and (toks[sig[jj]][1] == "," or
                           (toks[sig[jj]][0] == "n" and toks[sig[jj]][1] not in KEYWORDS)):
            jj -= 1
        if jj >= 0 and toks[sig[jj]][1] == "(":
            b = jj - 1
            while b >= 0 and (toks[sig[b]][0] == "n" and toks[sig[b]][1] != "function"
                              or toks[sig[b]][1] in (".", ":")):
                b -= 1
            if b >= 0 and toks[sig[b]][1] == "function":
                add(val)
                continue
        f = k + 1
        while f + 1 < len(sig) and toks[sig[f]][1] == "," and toks[sig[f + 1]][0] == "n":
            f += 2
        if f < len(sig) and toks[sig[f]][1] in ("=", "+=", "-=", "*=", "/=", "..=", "%=", "^=", "//="):
            add(val)
    return binds


def names_in(toks):
    return {t[1] for t in toks if t[0] == "n"}


def _rename_toks(toks, mapping):
    sig_prev = ""
    for t in toks:
        if t[0] == "n" and t[1] in mapping and sig_prev not in (".", ":"):
            t[1] = mapping[t[1]]
        if t[0] not in ("ws", "comment"):
            sig_prev = t[1]


# ---------------------------------------------------------------------------
# prettify: inline single-use global aliases (local vN = string -> use string)
# ---------------------------------------------------------------------------

def prettify(src):
    toks = tokenize(src)
    if toks is None:
        return src
    binds = analyze(toks)
    used = names_in(toks)
    sig = [i for i, t in enumerate(toks) if t[0] not in ("ws", "comment")]
    mapping = {}

    for k in range(len(sig) - 3):
        a, b, c, d = (toks[sig[k + x]] for x in range(4))
        if a[1] != "local" or b[0] != "n" or c[1] != "=":
            continue
        var = b[1]
        if not re.fullmatch(r"v\d+", var) or var in mapping:
            continue
        nxt = toks[sig[k + 4]][1] if k + 4 < len(sig) else ""
        # 1) local vN = <global>  -> inline the global
        if (binds.get(var, 0) == 1 and d[0] == "n" and d[1] in GLOBALS
                and nxt not in (".", ":", "(", "[", ",", "{")
                and binds.get(d[1], 0) == 0):
            mapping[var] = d[1]
            continue
        # 2) local vN = fn(lib, {...}) -> lib_lib
        if binds.get(var, 0) == 1 and d[0] == "n" and nxt == "(" and k + 5 < len(sig):
            lib = toks[sig[k + 5]][1]
            if lib in LIBS and toks[sig[k + 6]][1] == ",":
                new = lib + "_lib"
                n2 = 2
                while new in used or new in mapping.values():
                    new = "%s_lib%d" % (lib, n2)
                    n2 += 1
                mapping[var] = new

    _rename_toks(toks, mapping)
    out = "".join(t[1] for t in toks)
    out = re.sub(r"(?m)^[ \t]*local ([A-Za-z_]\w*) = \1[ \t]*\n", "", out)
    return out


# ---------------------------------------------------------------------------
# inline_consts: short single-use string/number locals -> inline literal
# ---------------------------------------------------------------------------

def inline_consts(text):
    decl = re.compile(
        r'(?m)^[ \t]*local ([A-Za-z_]\w*) = ("(?:[^"\\\n]|\\.){0,60}"|-?\d+(?:\.\d+)?)[ \t]*\n'
    )
    cands = {}
    for m in decl.finditer(text):
        cands.setdefault(m.group(1), []).append(m)
    for name, ms in cands.items():
        if len(ms) != 1 or name in KEYWORDS:
            continue
        m = re.search(
            r'(?m)^[ \t]*local ' + re.escape(name) +
            r' = ("(?:[^"\\\n]|\\.){0,60}"|-?\d+(?:\.\d+)?)[ \t]*\n', text
        )
        if not m:
            continue
        lit = m.group(1)
        rest = text[:m.start()] + text[m.end():]
        occ = list(re.finditer(r"(?<![\w.:])" + re.escape(name) + r"\b", rest))
        if not 1 <= len(occ) <= 3:
            continue
        bad = False
        for o in occ:
            after = rest[o.end():o.end() + 4]
            before = rest[max(0, o.start() - 7):o.start()]
            if (re.match(r"\s*(=[^=]|\+=|-=|\*=|/=|\.\.=|,)", after)
                    or before.rstrip().endswith(("local", "for", "function"))
                    or re.search(r"\bfunction\s*\w*\([^)]*$",
                                 rest[max(0, o.start() - 80):o.start()])):
                bad = True
                break
        if bad:
            continue
        if occ[0].start() < m.start():
            continue

        def rep(o, _lit=lit):
            nxt = o.string[o.end():o.end() + 1]
            return ("(" + _lit + ")" if nxt in (":", ".", "[", "(")
                    or (_lit.startswith("-") and o.string[o.start() - 2:o.start()] in ("- ", "^ "))
                    else _lit)

        text = re.sub(r"(?<![\w.:])" + re.escape(name) + r"\b", rep, rest)
    return text


# ---------------------------------------------------------------------------
# collapse_tables: {k=v, k=v} spanning multiple lines -> collapse if short
# ---------------------------------------------------------------------------

def collapse_tables(text):
    _INNER = re.compile(r"\{[^{}]*\}", re.S)

    def _one(m):
        inner = m.group(0)
        if "\n" not in inner:
            return inner
        flat = re.sub(r"\s+", " ", inner).strip()
        return flat if len(flat) <= 80 else inner

    prev = None
    for _ in range(6):
        text2 = _INNER.sub(_one, text)
        if text2 == prev:
            break
        prev, text = text2, text2
    return text


# ---------------------------------------------------------------------------
# sanitize: clean up engine-internal comments / labels
# ---------------------------------------------------------------------------

def _sim_note(m):
    msg = re.sub(r'^(?:(?:LPH|Script|\[string "[^"]*"\]):\d+:\s*)+', '',
                 m.group(2).strip())
    kinds = [
        ("call a nil value",      "calls a function the simulator does not provide"),
        ("compare",               "compares a number with an object the simulator only fakes"),
        ("index function with",   "uses an API result the simulator returns in a different form"),
        ("index nil",             "reads a value the simulator does not provide"),
        ("table index is nil",    "uses a key the simulator could not produce"),
        ("invalid argument",      "passes a fake object to a built-in function"),
        ("arithmetic",            "does math on a value the simulator only fakes"),
    ]
    why = next((w for k, w in kinds if k in msg),
               "hit something the simulator cannot reproduce")
    return ("%s-- [SL] note: the simulated run stopped in this branch "
            "(the script %s). Code above is valid; the rest of this branch "
            "was not traced." % (m.group(1), why))


_SANITIZE = [
    (r"(?m)^([ \t]*)--\s*\[envlog\]\s*error:\s*(.*)$",          _sim_note),
    (r"--\s*\[envlog\]\s*",                                       "-- [SL] "),
    (r"--\s*\[deobf\]\s*",                                        "-- [SL] "),
    (r"--\s*Luraph runtime function \(from the VM object, not part of the script: not lifted\)\.",
     "-- [SL] protected runtime function (cannot be recovered)."),
    (r"--\s*LPH_ENCFUNC decrypts a function this way: \(key, encrypted buffer, \.\.\.\) -> function\.",
     "-- [SL] decrypts an encrypted function: (key, buffer, ...) -> function."),
    (r'error\("Luraph runtime function, not devirtualized"\)',
     'error("SL: protected function")'),
    (r'error\("devirt: [^"\n]*"\)',                               'error("SL: this block could not be recovered")'),
    (r"\bluraph_runtime(\d+)\b",                                  r"protected_fn\1"),
    (r"the engine failed to devirtualize this part",              "this part could not be recovered"),
    (r"devirtualiz\w*",                                           "recover"),
    (r"--\[\[ the caller's registers \]\]",                       ""),
]


def sanitize(text):
    for a, b in _SANITIZE:
        text = re.sub(a, b, text)
    return text


# ---------------------------------------------------------------------------
# strip_comments: remove all tool-added comments
# ---------------------------------------------------------------------------

def strip_comments(text):
    text = re.sub(r"(?m)^[ \t]*--\[(=*)\[.*?\]\1\][ \t]*\n", "", text, flags=re.S)
    text = re.sub(r"--\[(=*)\[(?:(?!\n).)*?\]\1\]", "", text)
    out = []
    for line in text.split("\n"):
        st = line.strip()
        if st.startswith("--"):
            continue
        k = line.find("--")
        if k > 0:
            pre = line[:k]
            if (pre.count('"') % 2 == 0 and pre.count("'") % 2 == 0
                    and "[[" not in pre and "[=" not in pre):
                line = pre.rstrip()
        out.append(line)
    return "\n".join(out)


# ---------------------------------------------------------------------------
# smart_rename: scope-aware rename of generated names (v\d+, tbl\d+, fn\d*, arg\d*)
# ---------------------------------------------------------------------------

def _camel(s):
    parts = re.findall(r"[A-Za-z0-9]+", s)
    if not parts:
        return None
    out = (parts[0][0].lower() + parts[0][1:]
           + "".join(p[:1].upper() + p[1:] for p in parts[1:]))
    if not re.match(r"[A-Za-z_]", out):
        out = "_" + out
    return (out[:24] if out not in KEYWORDS else out + "Value")


def _name_from_init(init):
    init = init.strip()
    m = re.match(r"^\w+\((string|table|math|os|bit32|task|buffer|coroutine|utf8|debug),", init)
    if m:
        return m.group(1) + "_lib"
    m = re.match(r'^[\w.]+\.([\w]+)\s*$', init)
    if m:
        return _camel(m.group(1))
    m = re.match(r'^[\w.]+\[\s*"(\w+)"\s*\]\s*$', init)
    if m:
        return _camel(m.group(1))
    m = re.match(r'^Instance\.new\("(\w+)"', init)
    if m:
        return _camel(m.group(1))
    m = re.match(r'^\w+\(\s*[\w.]+\s*,\s*"([A-Za-z_][\w ]{0,30})"\s*\)\s*$', init)
    if m:
        return _camel(m.group(1))
    m = re.match(r'^\w+\(\s*"([A-Za-z_][\w ]{0,30})"\s*\)\s*$', init)
    if m:
        return _camel(m.group(1))
    m = re.match(r'^(?:get|Get|fetch|Fetch|read|Read|load|Load|create|Create|make|Make|build|Build)([A-Z]\w*)\(', init)
    if m:
        return _camel(m.group(1))
    for rx, nm in WORD_HINTS:
        if re.search(rx, init):
            if nm:
                return nm
    return None


def _multi_names(init, count):
    init = init.strip()
    if re.match(r"^x?pcall\(", init):
        base = ["ok", "result", "result2", "result3"]
        return base[:count]
    return None


class _Decl:
    __slots__ = ("old", "new", "kind", "hint", "idx")

    def __init__(self, old, kind, idx):
        self.old, self.kind, self.idx = old, kind, idx
        self.new, self.hint = None, None


PARAM_RULES = [
    ("Character",        "player"),  ("UserId",          "player"),
    ("DisplayName",      "player"),  ("Health",          "humanoid"),
    ("WalkSpeed",        "humanoid"), ("TakeDamage",     "humanoid"),
    ("HumanoidRootPart", "character"), ("KeyCode",       "input"),
    ("UserInputType",    "input"),   ("Disconnect",      "connection"),
    ("Position",         "part"),    ("CFrame",          "part"),
    ("lower",            "text"),    ("upper",           "text"),
    ("gsub",             "text"),    ("match",           "text"),
    ("IsA",              "instance"), ("FindFirstChild", "instance"),
    ("GetChildren",      "instance"), ("Parent",         "instance"),
    ("Destroy",          "instance"),
]

EVENT_PARAMS = {
    "PlayerAdded": ["player"], "PlayerRemoving": ["player"],
    "CharacterAdded": ["character"], "CharacterRemoving": ["character"],
    "InputBegan": ["input", "gameProcessed"], "InputEnded": ["input", "gameProcessed"],
    "InputChanged": ["input", "gameProcessed"],
    "Touched": ["hit"], "TouchEnded": ["hit"],
    "ChildAdded": ["child"], "ChildRemoved": ["child"],
    "DescendantAdded": ["descendant"], "DescendantRemoving": ["descendant"],
    "Heartbeat": ["deltaTime"], "RenderStepped": ["deltaTime"],
    "Stepped": ["time", "deltaTime"],
    "Changed": ["newValue"], "OnChanged": ["newValue"],
    "Died": [], "Chatted": ["message"],
}


def smart_rename(src):
    toks = tokenize(src)
    if toks is None:
        return src
    sig = [i for i, t in enumerate(toks) if t[0] not in ("ws", "comment")]
    S = [toks[i] for i in sig]
    n = len(S)
    used = {t[1] for t in S if t[0] == "n"}

    scopes = [{}]
    block_kinds = []
    pending = []
    ref = {}
    decls = []
    bdepth = 0
    brace_stack = []

    def lookup(name):
        for sc in reversed(scopes):
            if name in sc:
                return sc[name]
        return None

    def open_block(kind):
        scopes.append({})
        block_kinds.append(kind)

    def close_block():
        if len(scopes) > 1:
            scopes.pop()
            block_kinds.pop()

    def flush_pending(force=False):
        keep = []
        for ds, bd, kd in pending:
            if kd > len(block_kinds):
                continue
            if (force and kd == len(block_kinds)) or (bd == bdepth and kd == len(block_kinds)):
                for d in ds:
                    scopes[-1][d.old] = d
            else:
                keep.append((ds, bd, kd))
        pending[:] = keep

    def newline_between(a, b):
        for i in range(sig[a] + 1, sig[b]):
            if "\n" in toks[i][1]:
                return True
        return False

    fstack = []
    frecs = []
    for_header = None
    k = 0
    while k < n:
        kind, val = S[k]
        if k > 0 and pending and newline_between(k - 1, k):
            flush_pending()
        prev = S[k - 1][1] if k else ""

        if kind == "n" and val == "local" and k + 1 < n:
            if S[k + 1][1] == "function" and k + 2 < n and S[k + 2][0] == "n":
                d = _Decl(S[k + 2][1], "func", k + 2)
                decls.append(d)
                scopes[-1][d.old] = d
                ref[k + 2] = d
                k += 3
                continue
            j = k + 1
            ds = []
            while j < n and S[j][0] == "n":
                d = _Decl(S[j][1], "local", j)
                ds.append(d)
                decls.append(d)
                ref[j] = d
                j += 1
                if j < n and S[j][1] == ":":
                    j += 2
                if j < n and S[j][1] == ",":
                    j += 1
                else:
                    break
            if j < n and S[j][1] == "=":
                txt = []
                e = j + 1
                depth = 0
                while e < n:
                    if depth == 0 and e > j + 1 and newline_between(e - 1, e):
                        break
                    if S[e][1] in ("(", "[", "{"):
                        depth += 1
                    elif S[e][1] in (")", "]", "}"):
                        depth -= 1
                    txt.append(S[e][1])
                    e += 1
                init = " ".join(txt)
                init = re.sub(r"\s*([().,\[\]:#])\s*", r"\1", init).replace(",", ", ")
                if len(ds) == 1:
                    ds[0].hint = _name_from_init(init)
                else:
                    mn = _multi_names(init, len(ds))
                    if mn:
                        for d, h in zip(ds, mn):
                            d.hint = h
                pending.append((ds, bdepth, len(block_kinds)))
            else:
                for d in ds:
                    scopes[-1][d.old] = d
            k = j
            continue

        if kind == "n" and val == "function":
            j = k + 1
            if j < n and S[j][0] == "n":
                d = lookup(S[j][1])
                if d:
                    ref[j] = d
                j += 1
                while j + 1 < n and S[j][1] in (".", ":"):
                    j += 2
            open_block("function")
            rec = {"start": k, "end": n, "params": [], "depth": len(block_kinds),
                   "ctx": [S[x][1] for x in range(max(0, k - 6), k)]}
            fstack.append(rec)
            frecs.append(rec)
            if j < n and S[j][1] == "(":
                j += 1
                while j < n and S[j][1] != ")":
                    if S[j][0] == "n":
                        d = _Decl(S[j][1], "param", j)
                        rec["params"].append(d)
                        decls.append(d)
                        scopes[-1][d.old] = d
                        ref[j] = d
                        if j + 1 < n and S[j + 1][1] == ":":
                            j += 2
                    j += 1
                k = j + 1
                continue
            k = j
            continue

        if kind == "n" and val == "for":
            open_block("for")
            j = k + 1
            ds = []
            while j < n and S[j][0] == "n":
                d = _Decl(S[j][1], "for", j)
                ds.append(d)
                decls.append(d)
                ref[j] = d
                j += 1
                if j < n and S[j][1] == ",":
                    j += 1
                else:
                    break
            if j < n and S[j][1] == "in" and len(ds) >= 2:
                ds[0].hint = ds[0].hint or "key"
                ds[1].hint = "item" if (j + 1 < n and S[j + 1][1] == "ipairs") else "value"
            elif len(ds) == 1 and j < n and S[j][1] == "in":
                ds[0].hint = "item"
            if len(ds) >= 2 and j < n and S[j][1] == "in":
                e = j + 1
                if e + 1 < n and S[e][1] in ("pairs", "ipairs") and S[e + 1][1] == "(":
                    e += 2
                last = None
                while e < n and (S[e][0] == "n" or S[e][1] in (".", ":")) and S[e][1] not in ("do",):
                    if S[e][0] == "n":
                        last = S[e][1]
                    e += 1
                if (last and len(last) > 3 and last.endswith("s") and not last.endswith("ss")
                        and last not in ("pairs", "ipairs")):
                    sing = (last[:-3] + "y" if last.endswith("ies") else last[:-1])
                    nm = _camel(sing)
                    if nm and nm not in KEYWORDS:
                        ds[1].hint = nm
            for_header = ds
            k = j
            continue

        if kind == "n" and val == "do":
            if for_header is not None:
                for d in for_header:
                    scopes[-1][d.old] = d
                for_header = None
            elif block_kinds and block_kinds[-1] == "while_head":
                block_kinds[-1] = "while"
            else:
                open_block("do")
            k += 1
            continue
        if kind == "n" and val == "while":
            open_block("while_head")
            k += 1
            continue
        if kind == "n" and val == "then":
            open_block("then")
            k += 1
            continue
        if kind == "n" and val in ("elseif", "else"):
            flush_pending(force=True)
            close_block()
            if val == "else":
                open_block("then")
            k += 1
            continue
        if kind == "n" and val == "repeat":
            open_block("repeat")
            k += 1
            continue
        if kind == "n" and val == "end":
            flush_pending(force=True)
            if (fstack and fstack[-1]["depth"] == len(block_kinds)
                    and block_kinds and block_kinds[-1] == "function"):
                fstack.pop()["end"] = k
            close_block()
            k += 1
            continue
        if kind == "n" and val == "until":
            flush_pending(force=True)
            e = k + 1
            depth = 0
            while e < n:
                if depth == 0 and newline_between(e - 1, e):
                    break
                if S[e][1] in ("(", "[", "{"):
                    depth += 1
                elif S[e][1] in (")", "]", "}"):
                    depth -= 1
                if S[e][0] == "n" and S[e - 1][1] not in (".", ":"):
                    d = lookup(S[e][1])
                    if d:
                        ref[e] = d
                e += 1
            close_block()
            k = e
            continue

        if val in ("(", "["):
            bdepth += 1
        elif val == "{":
            bdepth += 1
            brace_stack.append(bdepth)
        elif val in (")", "]"):
            bdepth -= 1
        elif val == "}":
            if brace_stack:
                brace_stack.pop()
            bdepth -= 1

        if kind == "n" and val not in KEYWORDS and prev not in (".", ":", "::"):
            nxt = S[k + 1][1] if k + 1 < n else ""
            is_key = brace_stack and brace_stack[-1] == bdepth and prev in ("{", ",", ";") and nxt == "="
            if not is_key:
                d = lookup(val)
                if d:
                    ref[k] = d
        k += 1

    # usage-based hints
    refs_of = {}
    for k2, d in ref.items():
        refs_of.setdefault(id(d), []).append(k2)

    for d in decls:
        if d.hint and not re.match(r"(tbl|func|value|result|entry|str|num)\d*$", d.hint):
            continue
        rs = sorted(refs_of.get(id(d), []))
        if re.match(r"arg\d*$", d.old):
            feats = [S[r + 2][1] for r in rs if r + 2 < n and S[r + 1][1] in (".", ":")]
            for key, nm in PARAM_RULES:
                if key in feats:
                    d.hint = nm
                    break
        elif re.match(r"tbl\d+$", d.old):
            for r in rs:
                if r + 2 < n and S[r + 1][1] == "[" and S[r + 2][1] == "#":
                    d.hint = "list"
                    break
                if (r + 5 < n and S[r + 1][1] == "[" and S[r + 3][1] == "."
                        and S[r + 4][1] == "Name" and S[r + 5][1] == "]"):
                    d.hint = "byName"
                    break
        elif re.match(r"fn\d*$", d.old):
            for r in rs:
                if (r >= 2 and S[r - 1][1] == "=" and S[r - 2][0] == "n"
                        and (r + 1 >= n or S[r + 1][1] not in ("(", ".", ":", "["))):
                    nm = _camel(S[r - 2][1])
                    if nm and not re.match(r"(fn|tbl|v|arg)\d*$", nm):
                        d.hint = nm
                        break

    # event-param scoped names
    self_ok = {}
    scoped = []
    for rec in frecs:
        ps = rec["params"]
        if not ps:
            continue
        ctx = rec["ctx"]
        if (len(ctx) >= 2 and ctx[-1] == "="
                and ctx[-2] in ("Callback", "callback", "OnChanged", "Changed")):
            if re.match(r"arg\d*$", ps[0].old):
                scoped.append((ps[0], "value", rec))
            continue
        if (len(ctx) >= 4 and ctx[-1] == "("
                and ctx[-2] in ("Connect", "Once", "ConnectParallel", "OnChanged")
                and ctx[-3] == ":"):
            ev = ctx[-4]
            for d, nm in zip(ps, EVENT_PARAMS.get(ev, [])):
                if re.match(r"arg\d*$", d.old):
                    scoped.append((d, nm, rec))
            continue
        if (len(ctx) >= 4 and ctx[-1] == "=" and ctx[-3] in (".", ":")
                and re.match(r"arg$", ps[0].old)):
            body = [S[x][1] for x in range(rec["start"], min(rec["end"], n))]
            if "self" in body:
                continue
            rs = refs_of.get(id(ps[0]), [])
            STR_M = ("find", "sub", "match", "gmatch", "gsub", "lower", "upper",
                     "len", "split", "rep", "byte", "format")
            dot = any(r + 2 < n and S[r + 1][1] == "." for r in rs)
            strm = any(r + 2 < n and S[r + 1][1] == ":" and S[r + 2][1] in STR_M for r in rs)
            fname = ctx[-2]
            method_call = any(S[x][1] == ":" and S[x + 1][1] == fname
                              and S[x + 2][1] in ("(", "{", '"')
                              for x in range(n - 2))
            if method_call and not strm:
                scoped.append((ps[0], "self", rec))
            elif strm and not dot:
                scoped.append((ps[0], "text", rec))
            elif dot and not strm:
                scoped.append((ps[0], "obj", rec))

    given = []
    for d, nm, rec in scoped:
        a, b = rec["start"], min(rec["end"], n)
        body = {S[x][1] for x in range(a, b) if S[x][0] == "n"}
        if nm in body or nm in KEYWORDS:
            continue
        if any(g == nm and ga <= a and b <= gb for g, ga, gb in given):
            continue
        given.append((nm, a, b))
        self_ok[id(d)] = nm

    taken = set(used) | {g for g, _, _ in given}
    for d in decls:
        if id(d) in self_ok and TARGET_RE.match(d.old):
            d.new = self_ok[id(d)]
            continue
        if not TARGET_RE.match(d.old) or not d.hint:
            continue
        if (not re.match(r"v\d+$", d.old)
                and re.match(r"(tbl|func|value|result|entry|str|num|fn|arg)\d*$", d.hint)):
            continue
        base = d.hint
        if id(d) in self_ok:
            d.new = self_ok[id(d)]
            continue
        new = base
        c = 2
        while new in taken or new in KEYWORDS or new in GLOBALS:
            new = "%s%d" % (base, c)
            c += 1
        taken.add(new)
        d.new = new

    for k, d in ref.items():
        if d.new and S[k][1] == d.old:
            S[k][1] = d.new
    return "".join(t[1] for t in toks)


# ---------------------------------------------------------------------------
# Watermark injection
# ---------------------------------------------------------------------------

DISCORD       = "https://discord.gg/x7YbZeezpm"
DISCORD_SHORT = "discord.gg/x7YbZeezpm"
ZW = "\u200b"


def _style(text, table):
    out = []
    for ch in text:
        if "A" <= ch <= "Z":
            out.append(chr(table[0] + ord(ch) - 65))
        elif "a" <= ch <= "z":
            out.append(chr(table[1] + ord(ch) - 97))
        else:
            out.append(ch)
    return "".join(out)


_FONTS = [
    lambda s: s,
    lambda s: _style(s, (0x1D400, 0x1D41A)),
    lambda s: _style(s, (0x1D5A0, 0x1D5BA)),
    lambda s: _style(s, (0x1D670, 0x1D68A)),
    lambda s: _style(s, (0x1D5D4, 0x1D5EE)),
    lambda s: "".join(
        chr(0xFF21 + ord(c) - 65) if "A" <= c <= "Z" else
        chr(0xFF41 + ord(c) - 97) if "a" <= c <= "z" else c
        for c in s),
    lambda s: s.upper(),
    lambda s: ZW.join(s),
]

_TEMPLATES = [
    "-- {sl} | "       + DISCORD,
    "-- "              + DISCORD + " | {sl}",
    "--[[ {sl} :: "    + DISCORD_SHORT + " ]]",
    "-- deobfuscated by {sl} -> " + DISCORD,
    "--[=[ {sl} ]=] -- " + DISCORD_SHORT,
    "-- join us: "     + DISCORD,
    "-- {sl} // "      + DISCORD_SHORT,
    "-- more leaks: "  + DISCORD,
]
_NAMES = ["SL | Source Leak", "Source Leak", "SL", "Source Leak (SL)"]


def _wmark(rng):
    font = rng.choice(_FONTS)
    tpl = rng.choice(_TEMPLATES)
    return tpl.replace("{sl}", font(rng.choice(_NAMES)))


def scatter_watermarks(text):
    import random, hashlib
    toks = tokenize(text)
    if toks is None:
        return text
    lines_total = text.count("\n") + 1
    want = max(1, min(12, lines_total // 300))
    if lines_total < 40:
        want = 0 if lines_total < 15 else 1
    offs, pos = [], 0
    for kind, val in toks:
        if kind == "ws" and "\n\n" in val:
            cut = val.index("\n\n") + 1
            nxt = val[cut:].split("\n")
            indent = nxt[-1] if nxt else ""
            offs.append((pos + cut, indent))
        pos += len(val)
    if not offs or want == 0:
        return text
    rng = random.Random(hashlib.md5(text.encode("utf-8", "replace")).hexdigest())
    n = len(offs)
    lo, hi = int(n * 0.05), max(int(n * 0.95), 1)
    picks = set()
    for i in range(want):
        a = lo + (hi - lo) * i // want
        b = lo + (hi - lo) * (i + 1) // want
        if b > a:
            picks.add(rng.randrange(a, b))
    for idx in sorted(picks, reverse=True):
        off, indent = offs[idx]
        text = text[:off] + indent + _wmark(rng) + "\n" + text[off:]
    return text


def footer_watermark(text):
    import random, hashlib
    rng = random.Random(hashlib.sha1(text.encode("utf-8", "replace")).hexdigest())
    return text.rstrip("\n") + "\n\n" + _wmark(rng) + "\n"


# ---------------------------------------------------------------------------
# finalize: full post-processing pipeline
# ---------------------------------------------------------------------------

def enabled():
    """The SL post-processor is opt-in (DEOB_SL_POST=1). It strips every
    comment (including the engine's own "unresolved"/"not original source"
    notes) and adds third-party watermark/advert lines to the output, so it
    must never run unless asked for. It also failed to import (corrupted
    regex literals) in the supplied export, i.e. it has never run in production."""
    return os.environ.get("DEOB_SL_POST") == "1"


def finalize(text):
    if not enabled():
        return text
    # 1. sanitize engine labels
    text = sanitize(text)

    # 2. inline single-use short constants
    try:
        text = collapse_tables(inline_consts(text))
    except Exception:
        pass

    # 3. drop engine no-op artefact
    text = re.sub(r"(?m)^[ \t]*local \.\.\. = \.\.\.[ \t]*\n", "", text)

    # 4. fix statement-starting "(" ambiguity
    _ls = text.split("\n")
    for _i, _l in enumerate(_ls):
        if re.match(r"[ \t]*\([^\n]*\)[.:\[(]", _l):
            _j = _i - 1
            while _j >= 0 and not _ls[_j].strip():
                _j -= 1
            if _j >= 0:
                _p = _ls[_j].rstrip()
                if (re.search(r"[\w)\]\"\'}]$", _p)
                        and not re.search(
                            r"(\W)(then|do|else|repeat|return|and|or|not|in|local|function)$",
                            _p)
                        and not _p.lstrip().startswith("--")):
                    _ls[_j] = _p + ";"
    text = "\n".join(_ls)

    # 5. clean up for-in with trailing nils
    text = re.sub(
        r"(?m)^(\s*for [^\n]*? in [A-Za-z_][\w.]*), nil, nil do$",
        r"\1 do", text
    )

    # 6. turn unlifted-block errors into comments
    text = re.sub(
        r'(?m)^([ \t]*)error\("devirt: [^\n]*"\)[ \t]*$',
        r'\1-- [SL] the engine could not recover this block',
        text
    )
    text = re.sub(
        r'(?m)^([ \t]*)error\("SL: this block could not be recovered"\)[ \t]*$',
        r'\1-- [SL] the engine could not recover this block',
        text
    )

    # 7. prettify (global alias inlining)
    try:
        text = prettify(text)
    except Exception:
        pass

    # 8. smart rename (scope-aware v\d+ / tbl\d+ etc.)
    try:
        text = smart_rename(text)
    except Exception:
        pass

    # 9. trim tool status comments at top
    lines = [l.rstrip() for l in text.replace("\r\n", "\n").split("\n")]
    while lines and (
        not lines[0].strip()
        or re.match(r"--\s*(run status|\d+ statements recorded|\[deobf\])", lines[0])
    ):
        lines.pop(0)
    text = re.sub(r"\n{3,}", "\n\n", "\n".join(lines)).strip("\n")

    # 10. strip tool-added comments
    try:
        text = strip_comments(text)
        text = re.sub(r"\n{3,}", "\n\n", text).strip("\n")
    except Exception:
        pass

    # 11. scatter watermarks + footer
    try:
        text = scatter_watermarks(text)
        text = footer_watermark(text)
    except Exception:
        text += "\n"

    return WATERMARK + "\n" + text


def process_file(path):
    """In-place finalize on a UTF-8 file."""
    if not enabled():
        return
    with open(path, encoding="utf-8", errors="replace") as f:
        text = f.read()
    with open(path, "w", encoding="utf-8", newline="\n") as f:
        f.write(finalize(text))
